import React, { useEffect, useRef, useState } from 'react'
import { Helmet } from 'react-helmet-async'
import { useNavigate, useParams } from 'react-router'

import ArrowBackIcon from '@mui/icons-material/ArrowBack'
import {
  Box,
  Button,
  Card,
  CardHeader,
  Checkbox,
  Container,
  Divider,
  TextField,
  Typography,
  useMediaQuery,
  useTheme
} from '@mui/material'
import { extractImageUrls } from 'src/utils/extractImageUrls'

import CancelSubmitBtns from 'src/components/CancelSubmitBtns'
import TextEditor, { type TextEditorHandle } from 'src/components/TextEditor'

import { useCreateActivityPost, useGetActivityPost, usePatchActivityPost } from 'src/hooks/api/activityHooks'

const ActivityPostEdit: React.FC = () => {
  const navigate = useNavigate()
  const theme = useTheme()
  const isUpSm = useMediaQuery(theme.breakpoints.up('sm'))

  const handleClickNavigateBack: React.MouseEventHandler<HTMLButtonElement> = () => {
    navigate(-1)
  }

  const editorRef = useRef<TextEditorHandle>(null)
  const { id, postId } = useParams()
  const clubId = Number(id)
  const activityPostId = postId ? Number(postId) : null

  const [title, setTitle] = useState<string>('')
  const [isPublic, setIsPublic] = useState<boolean>(true)

  const { data, isSuccess } = useGetActivityPost(clubId, activityPostId ?? 0)

  useEffect(() => {
    if (isSuccess && data && activityPostId) {
      setTitle(data.title)
      setIsPublic(data.isPublic)
      editorRef.current?.setHTML(data.note || '')
    }
  }, [isSuccess, data, activityPostId])

  const createMutation = useCreateActivityPost(clubId)
  const patchMutation = usePatchActivityPost(clubId, activityPostId ?? 0)

  const handleSubmit = () => {
    const content = editorRef.current?.getHTML() || ''
    const imageUrls = extractImageUrls(content)

    const requestData = {
      title,
      note: content,
      imageUrls,
      isPublic,
      categories: []
    }

    if (activityPostId) {
      patchMutation.mutate(requestData)
    } else {
      createMutation.mutate(requestData)
    }
  }

  const handleTitleChange: React.ChangeEventHandler<HTMLInputElement> = e => {
    setTitle(e.target.value)
  }

  return (
    <Box m={3}>
      <Helmet>
        <title>{activityPostId ? '활동 포스팅 수정' : '활동 포스팅 작성'}</title>
      </Helmet>
      <Container>
        <Card>
          <Box
            sx={{ display: 'flex', flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', p: 1 }}
          >
            <Box sx={{ display: 'flex', flexDirection: 'row', alignItems: 'center' }}>
              <Button variant="text" onClick={handleClickNavigateBack} color="primary">
                <ArrowBackIcon />
              </Button>
              <CardHeader title={activityPostId ? '활동 포스팅 수정' : '활동 포스팅 작성'} />
            </Box>
            <Box>
              <Typography display="inline-block" variant="body1">
                전체 공개
              </Typography>
              <Checkbox sx={{ padding: '5px' }} checked={isPublic} onChange={e => setIsPublic(e.target.checked)} />
            </Box>
          </Box>
          <Divider />
          <Box sx={{ p: isUpSm ? 3 : 2 }}>
            <TextField
              fullWidth
              label="제목"
              value={title}
              onChange={handleTitleChange}
              sx={{ mb: 2 }}
              required
              inputProps={{ maxLength: 200 }}
            />
            <TextEditor
              initialValue={activityPostId && data ? data.note : ''}
              ref={editorRef}
              toolbarItems={[
                ['heading', 'bold', 'italic', 'strike'],
                ['hr', 'quote'],
                ['ul', 'ol', 'task'],
                ['image', 'link'],
                ['code', 'codeblock']
              ]}
              imageUploadEndpoint={`${process.env.REACT_APP_APIHOST}/club/${clubId}/activity/img`}
            />
          </Box>
        </Card>
        <CancelSubmitBtns handleSubmit={handleSubmit} submitBtnText={activityPostId ? '수정' : '등록'} />
      </Container>
    </Box>
  )
}

export default ActivityPostEdit
